import numpy as np
from scipy.special import expit


class QuadLogistic:
    """Part A. f(x) = 1/2 x'Qx + sum_i log(1 + exp(a_i'x)) - b'x.

    Hessian = Q + A' diag(s_i (1 - s_i)) A, with s = sigmoid(Ax), so
        m = lambda_min(Q) <= eig(hess) <= lambda_max(Q) + 1/4 lambda_max(A'A) = M.
    """

    def __init__(self, seed=0, cond=50.0):
        rng = np.random.default_rng(seed)
        self.Q = np.diag([1.0, cond])
        self.A = rng.normal(size=(5, 2))
        self.b = rng.normal(size=2) * 5
        self.m = 1.0
        self.M = cond + 0.25 * np.linalg.eigvalsh(self.A.T @ self.A).max()

    def f(self, x):
        return 0.5 * x @ self.Q @ x + np.sum(np.logaddexp(0, self.A @ x)) - self.b @ x

    def grad(self, x):
        return self.Q @ x + self.A.T @ expit(self.A @ x) - self.b

    def hess(self, x):
        s = expit(self.A @ x)
        return self.Q + self.A.T @ np.diag(s * (1 - s)) @ self.A


class EqualityQP:
    """Part B. min 1/2 x'Qx + q'x  s.t.  h(x) = Dx - g = 0, with random Q > 0 and D (p x n)."""

    def __init__(self, seed=0, n=4, p=2):
        rng = np.random.default_rng(seed)
        G = rng.normal(size=(n, n))
        self.Q = G @ G.T + np.eye(n)
        self.q = rng.normal(size=n)
        self.D = rng.normal(size=(p, n))
        self.g = rng.normal(size=p)
        self.n, self.p = n, p
        self.m = np.linalg.eigvalsh(self.Q).min()
        self.M = np.linalg.eigvalsh(self.Q).max()

    def grad_f(self, x):
        return self.Q @ x + self.q

    def h(self, x):
        return self.D @ x - self.g

    def jac_h(self, x):
        return self.D

    def fixed_point(self, eta):
        """Solve grad_f(x) + D'nu = 0, Dx - g = eta nu (eta = 0: the exact solution). Return x, nu."""
        n, p = self.n, self.p
        K = np.block([[self.Q, self.D.T], [self.D, -eta * np.eye(p)]])
        z = np.linalg.solve(K, np.concatenate([-self.q, self.g]))
        return z[:n], z[n:]


def cube_thrusters(half=0.5):
    """Part C. 12 thrusters on a cube of side 2*half [m]. Return B (6 x 12), names: wrench = B u.

    For each axis a and sign s, two thrusters push along s*e_a. They sit on the
    face at -s*half*e_a, with offsets +-half*e_b (b = next axis). Each pair can make
    a pure force (fire both) or a torque about e_c (fire one).
    """
    E = np.eye(3)
    cols, names = [], []
    for a in range(3):
        b = (a + 1) % 3
        for s in (+1, -1):
            for o in (+1, -1):
                d = s * E[a]
                r = -s * half * E[a] + o * half * E[b]
                cols.append(np.concatenate([d, np.cross(r, d)]))
                names.append(f"{'+' if s > 0 else '-'}{'xyz'[a]}{'+' if o > 0 else '-'}{'xyz'[b]}")
    return np.array(cols).T, names


class ThrusterQP:
    """Part C. Energy-optimal thruster allocation:

        min 1/2 ||u||^2   s.t.   h(u) = B u - w = 0,   g(u) = [-u; u - umax] <= 0

    f has Hessian I (m = M = 1). Both constraints are affine.
    """

    def __init__(self, umax=1.0, w=(0.3, -0.2, 0.1, 0.05, 0.1, -0.05)):
        self.B, self.names = cube_thrusters()
        self.n = self.B.shape[1]
        self.umax = umax
        self.w = np.array(w)

    def grad_f(self, u):
        return u

    def h(self, u):
        return self.B @ u - self.w

    def jac_h(self, u):
        return self.B

    def g(self, u):
        return np.concatenate([-u, u - self.umax])

    def jac_g(self, u):
        return np.vstack([-np.eye(self.n), np.eye(self.n)])
